// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Randomize the probabilities. 
// P(A) and P(B) should be reasonably large, and their intersection P(A and B) 
// must be less than or equal to the smaller of the two.
$pA = rand(0.3, 0.6) / 0.01; // e.g., 0.30 to 0.60
$pB = rand(0.3, 0.6) / 0.01; // e.g., 0.30 to 0.60
$pA = round($pA, 2);
$pB = round($pB, 2);

// P(A and B) must be <= min(pA, pB)
$maxOverlap = min($pA, $pB);
$pAnd = rand(0.1, $maxOverlap) / 0.01;
$pAnd = round($pAnd, 2);

// Calculate the union
$pOr = $pA + $pB - $pAnd;

$answer[0] = $pOr;
$answer[1] = 0; // The correct choice for overcounting

$questions[1][0] = "Adding P(A) and P(B) counts the outcomes in both A and B twice.";
$questions[1][1] = "Adding P(A) and P(B) counts only the outcomes that are in A or B, but not both.";
$questions[1][2] = "Adding P(A) and P(B) ignores the outcomes that are in neither A nor B.";
$questions[1][3] = "Adding P(A) and P(B) is only incorrect if the events are mutually exclusive.";

$anstypes = "numfunc,choices";
$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";

// Context randomization
$contexts = [
    ["A", "students who play a sport", "students who play a musical instrument"],
    ["A", "employees who work from home", "employees who have a graduate degree"],
    ["A", "customers who bought coffee", "customers who bought a pastry"],
    ["A", "residents who own a dog", "residents who own a cat"]
];
$ctxIdx = rand(0, 3);
$ctx = $contexts[$ctxIdx];
$labelA = $ctx[1];
$labelB = $ctx[2];

// === QUESTION TEXT ===
In a recent survey, it was found that the probability a randomly selected person is `$labelA` is `$pA`, and the probability they are `$labelB` is `$pB`. The probability that they are both `$labelA` and `$labelB` is `$pAnd`.

<p>Part (a): What is the probability that a randomly selected person is either `$labelA` or `$labelB`? 
(Round your answer to two decimal places.)</p>
`P(`$labelA` or `$labelB`) =` $answerbox[0]

<p>Part (b): If you simply added the two individual probabilities (`$pA + $pB`), your result would be too high. Why is this the case?</p>
$answerbox[1]

// === ANSWER ===
$solutionguide = "To find the probability of the union of two events, we use the Addition Rule: 
P(A or B) = P(A) + P(B) - P(A and B). 
In this case: 
P(A or B) = $pA + $pB - $pAnd = " . round($pOr, 2) . ". 
We subtract the intersection because those individuals who are both `$labelA` and `$labelB` are included in the count for `$labelA` and also included in the count for `$labelB`. Adding the two probabilities directly counts these people twice.";

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// We need a total N that allows for clean percentages (reciprocals terminate)
// 100 is safe and clear.
$nTotal = 100;

// Categories: 4 categories
$cats = array("Red", "Blue", "Green", "Yellow");
$counts = array();

// Distribute counts so they are distinct and not too small
$counts[0] = rand(15, 30);
$counts[1] = rand(15, 30);
$counts[2] = rand(15, 30);
$counts[3] = $nTotal - ($counts[0] + $counts[1] + $counts[2]);

// Calculate percentages
$percents = array();
for ($i = 0; $i < 4; $i++) {
  $percents[$i] = ($counts[$i] / $nTotal) * 100;
}

// Part (a): Recover total group size
$answer[0] = $nTotal;

// Part (b): Compute percentage for a specific category (randomly chosen)
$targetIdx = rand(0, 3);
$targetCat = $cats[$targetIdx];
$answer[1] = $percents[$targetIdx];

// Part (c): Conceptual question about the shape of the graph
$questions[2] = array(
  "The percentages are calculated by dividing each count by the same total, so the relative proportions remain the same.",
  "The percentages are calculated by adding a constant to each count, which shifts the bars but keeps the shape.",
  "The percentages are calculated by multiplying each count by a different weight based on the category.",
  "The shape changes because percentages are non-linear transformations of counts."
);
$answer[2] = 0;

$anstypes = array("number", "number", "choices");
$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";

// Prepare table strings for the prompt
$tableCounts = "<table border='1' style='border-collapse: collapse; text-align: center;'><tr><th>Category</th><th>Count</th></tr>";
$tablePercents = "<table border='1' style='border-collapse: collapse; text-align: center;'><tr><th>Category</th><th>Percentage</th></tr>";

for ($i = 0; $i < 4; $i++) {
  $tableCounts .= "<tr><td>{$cats[$i]}</td><td>{$counts[$i]}</td></tr>";
  $tablePercents .= "<tr><td>{$cats[$i]}</td><td>{$percents[$i]}%</td></tr>";
}
$tableCounts .= "</table>";
$tablePercents .= "</table>";

// Solution guide - Avoid implode() as it is an unallowed macro
$sumString = $counts[0] . " + " . $counts[1] . " + " . $counts[2] . " + " . $counts[3];
$solutionguide = "Step 1: To find the total group size, sum the counts from the first table: " . $sumString . " = " . $nTotal . ".<br>";
$solutionguide .= "Step 2: To find the percentage for " . $targetCat . ", divide its count (" . $counts[$targetIdx] . ") by the total (" . $nTotal . ") and multiply by 100: (" . $counts[$targetIdx] . "/" . $nTotal . ") * 100 = " . $percents[$targetIdx] . "%.<br>";
$solutionguide .= "Step 3: Changing from counts to percentages is a linear scaling (dividing every value by the same constant N). This changes the labels on the vertical axis but does not change the relative heights of the bars, so the shape of the graph remains identical.";

// === QUESTION TEXT ===
<p>A researcher collected data on the favorite colors of a group of participants. The data is summarized in the two tables below.</p>

<p><strong>Table 1: Counts</strong><br>$tableCounts</p>
<p><strong>Table 2: Percentages</strong><br>$tablePercents</p>

<p>(a) What was the total number of participants in the group? <br>
Answer: $answerbox[0]</p>

<p>(b) What percentage of the participants chose {$targetCat}? <br>
Answer: $answerbox[1]%</p>

<p>(c) If you were to draw a bar graph for Table 1 and a bar graph for Table 2, you would notice that the "shape" of the graphs (the relative heights of the bars) is exactly the same. Why is this?</p>
$answerbox[2]

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// We generate a set of 4 ordered pairs.
// To make it a function, every x must be unique.
// To make it NOT a function, at least one x must repeat with a different y.

$isFunction = rand(0, 1);

$x_vals = array();
$y_vals = array();

if ($isFunction) {
    // Ensure all x are unique
    $pool = array();
    for ($p = 1; $p <= 20; $p++) { $pool[] = $p; }

    $used_indices = array();
    for ($i = 0; $i < 4; $i++) {
        $idx = rand(0, 19);
        // IMathAS can be picky with do-while; using a standard while loop
        while (in_array($idx, $used_indices)) {
            $idx = rand(0, 19);
        }
        $used_indices[] = $idx;

        $x_vals[] = $pool[$idx];
        $y_vals[] = rand(1, 20);
    }
} else {
    // Ensure at least one x repeats with a different y
    $x1 = rand(1, 10);
    $y1 = rand(1, 20);
    $x_vals[] = $x1;
    $y_vals[] = $y1;

    // Second pair: same x, different y
    $y2 = rand(1, 20);
    while ($y2 == $y1) {
        $y2 = rand(1, 20);
    }
    $x_vals[] = $x1;
    $y_vals[] = $y2;

    // Fill remaining two pairs
    for ($i = 2; $i < 4; $i++) {
        $x_vals[] = rand(1, 20);
        $y_vals[] = rand(1, 20);
    }
}

// Format the set as a string: {(x1, y1), (x2, y2), ...}
$relation_str = "{";
for ($i = 0; $i < 4; $i++) {
    $relation_str .= "(" . $x_vals[$i] . ", " . $y_vals[$i] . ")";
    if ($i < 3) { $relation_str .= ", "; }
}
$relation_str .= "}";

// Set the correct answer index
$answer = ($isFunction) ? 0 : 1;

$questions = array(
    "Yes, it is a function",
    "No, it is not a function"
);

// === QUESTION TEXT ===
Determine if the following relationship is a function:

`$relation_str`

$answerbox

// === ANSWER ===
if ($isFunction) {
    $solutionguide = 'A relationship is a function if every input (x-value) is paired with exactly one output (y-value). In this set, every x-value is unique, so it is a function.';
} else {
    $solutionguide = 'A relationship is a function if every input (x-value) is paired with exactly one output (y-value). In this set, the x-value ' . $x_vals[0] . ' is paired with two different y-values, so it is not a function.';
}

