// === NAME - DESCRIPTION: Normal Distribution - Critical Z values and invNorm area logic ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Part 1: Right-tail area.
$rightArea = randfrom(array(0.05, 0.025, 0.01, 0.10));
$leftArea = 1 - $rightArea;

// Use a lookup table with keys that match the precision of the generated values.
// We use strings to avoid floating point precision issues in array keys.
$zTable = array(
  "0.90" => 1.282,
  "0.95" => 1.645,
  "0.975" => 1.960,
  "0.99" => 2.326,
  "0.01" => -2.326,
  "0.025" => -1.960,
  "0.05" => -1.645,
  "0.10" => -1.282,
  "0.005" => -2.576
);

// Convert the calculated area to a string formatted to match the table keys.
// Since $rightArea is from a fixed list, $leftArea will be 0.90, 0.95, 0.975, or 0.99.
$leftAreaStr = (string)$leftArea;
$zRight = $zTable[$leftAreaStr];

// Part 2: Middle area.
$midPct = randfrom(array(90, 95, 99));
$midArea = $midPct / 100;
$tailArea = (1 - $midArea) / 2;
$leftMidArea = $tailArea;

// Convert the tail area to a string to match the table keys.
// For 90%, tail is 0.05. For 95%, tail is 0.025. For 99%, tail is 0.005.
$leftMidAreaStr = (string)$leftMidArea;
$zMid = $zTable[$leftMidAreaStr];

$answer[0] = $leftArea;
$answer[1] = $zRight;
$answer[2] = $zMid;

$anstypes = "numfunc,numfunc,numfunc";
$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";
$strflags[2] = "trim_whitespace";

// === QUESTION TEXT ===
Consider a standard normal distribution with mean `\mu = 0` and standard deviation `\sigma = 1`.

<p>Part (a): You want to find the critical value `z` such that the area to the right of `z` is `$rightArea`. 
Since the `invNorm` function on most calculators calculates the area to the left, what area should you enter into the function to find this `z`?
<br>Area to the left = $answerbox[0]</p>

<p>Part (b): Using the area from part (a), find the critical value `z` rounded to three decimal places.
<br>`z =` $answerbox[1]</p>

<p>Part (c): Find the critical value `z` that bounds the middle `$midPct%` of the standard normal curve (specifically, the negative `z` value that marks the lower boundary of this middle region), rounded to three decimal places.
<br>`z =` $answerbox[2]</p>

// === ANSWER ===
$solutionguide = 'Part (a): The total area under the curve is 1. If the area to the right is ' . $rightArea . ', the area to the left is ' . (1 - $rightArea) . '. Since invNorm uses left-tail areas, we use ' . $leftArea . '.
Part (b): Using invNorm(' . $leftArea . ', 0, 1), we find z = ' . $zRight . '.
Part (c): For the middle ' . $midPct . '%, the remaining area is ' . (100 - $midPct) . '%. This is split equally between the two tails, so each tail has an area of ' . round($tailArea, 4) . '. The lower boundary is the z-score with a left-tail area of ' . round($leftMidArea, 4) . '. Using invNorm(' . round($leftMidArea, 4) . ', 0, 1), we find z = ' . $zMid . '.';

